The list shows "1 items". What does it show after one click on Add?

```jsx
class List extends PureComponent {
  render() {
    return <p>{this.props.items.length} items</p>;
  }
}

class App extends Component {
  state = { items: ['a'] };
  add = () => {
    this.state.items.push('b');
    this.setState({ items: this.state.items });
  };
  render() {
    return (
      <>
        <button onClick={this.add}>Add</button>
        <List items={this.state.items} />
      </>
    );
  }
}
```

