Each card in a long feed must log an impression **once**, when at least half of it has been visible, without scroll listeners. Which effect meets the requirement?

```jsx
// Version 1
useEffect(() => {
  const el = ref.current;
  const io = new IntersectionObserver(([entry]) => {
    if (entry.intersectionRatio >= 0.5) { logImpression(id); io.unobserve(el); }
  }, { threshold: 0.5 });
  io.observe(el);
  return () => io.disconnect();
}, [id]);

// Version 2
useEffect(() => {
  const io = new IntersectionObserver(([entry]) => {
    if (entry.intersectionRatio >= 0.5) logImpression(id);
  }, { threshold: 0.5 });
  io.observe(ref.current);
  return () => io.disconnect();
}, [id]);

// Version 3
useEffect(() => {
  const onScroll = () => {
    const r = ref.current.getBoundingClientRect();
    if (r.top < innerHeight && r.bottom > 0) logImpression(id);
  };
  window.addEventListener('scroll', onScroll);
  return () => window.removeEventListener('scroll', onScroll);
}, [id]);

// Version 4
useEffect(() => {
  const io = new IntersectionObserver(([entry]) => {
    if (entry.intersectionRatio >= 0.5) { logImpression(id); io.unobserve(ref.current); }
  }, { threshold: 0.5 });
  io.observe(ref.current);
}, [id]);
```

With the thunk middleware installed, you need `fetchUser(id)` to skip the request if the user is already cached, and otherwise track loading, success and failure in the store. Which implementation is correct?

```js
// Version 1
const fetchUser = (id) => async (dispatch, getState) => {
  if (getState().users.byId[id]) return;
  dispatch({ type: 'user/pending', id });
  try {
    const user = await api.getUser(id);
    dispatch({ type: 'user/fulfilled', user });
  } catch (err) {
    dispatch({ type: 'user/rejected', id, error: err.message });
  }
};

// Version 2
const fetchUser = (id) => async (dispatch) => {
  const user = await api.getUser(id);
  return { type: 'user/fulfilled', user };
};

// Version 3: inside the users reducer
case 'user/fetch':
  return api.getUser(action.id).then((user) => ({ ...state, [user.id]: user }));

// Version 4
const fetchUser = (id) => (dispatch) => {
  dispatch(api.getUser(id));
};
```

A store is created with Redux's `applyMiddleware(thunk, logger)`, where:

```js
const thunk = ({ dispatch, getState }) => (next) => (action) =>
  typeof action === 'function' ? action(dispatch, getState) : next(action);

const logger = () => (next) => (action) => {
  console.log(typeof action === 'function' ? 'fn' : action.type);
  return next(action);
};

store.dispatch((dispatch) => {
  dispatch({ type: 'a' });
});
