When every light is on, `deactivating` becomes `true`, and lights must turn off one by one, 300 ms apart, from the end of `order`. If the user leaves the page mid-way, no timer may keep running. Which effect is correct?

```jsx
// Version 1
useEffect(() => {
  if (!deactivating) return;
  if (order.length === 0) { setDeactivating(false); return; }
  const id = setTimeout(() => setOrder(o => o.slice(0, -1)), 300);
  return () => clearTimeout(id);
}, [deactivating, order]);

// Version 2
useEffect(() => {
  if (!deactivating) return;
  const id = setInterval(() => setOrder(order.slice(0, -1)), 300);
  return () => clearInterval(id);
}, [deactivating]);

// Version 3
useEffect(() => {
  if (!deactivating) return;
  order.forEach((_, k) => {
    setTimeout(() => setOrder(o => o.slice(0, -1)), 300 * (k + 1));
  });
}, [deactivating]);

// Version 4
useEffect(() => {
  if (!deactivating) return;
  const id = setInterval(() => { order.pop(); setOrder(order); }, 300);
  return () => clearInterval(id);
}, [deactivating]);
```

A weekly calendar highlights the selected day (stored in state) and lays out the Sunday-to-Saturday week around it:

```js
function getWeekDays(date) {
  const start = date;
  start.setDate(start.getDate() - start.getDay());
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    return d;
  });
}

const [selected, setSelected] = useState(new Date(2026, 9, 14)); // Wed 14 Oct
const days = getWeekDays(selected);
```

The week shows Sun 11 to Sat 17 correctly, but the highlight sits on Sunday 11 instead of Wednesday 14. Why?

